  startedAt      DateTime?
  completedAt    DateTime?
}

model BillingInvoice {
  id         String               @id
  payerId    String
  sourceType String
  sourceId   String
  status     String
  totalCents Int
  issuedAt   DateTime
  lines      BillingInvoiceLine[]

  @@unique([sourceType, sourceId])
}

model BillingInvoiceLine {
  id          String         @id
  invoiceId   String
  code        String
  description String
  amountCents Int
